import inspect


def get_arg_info(arg_name, passed_args, passed_kwargs, func):
    args_names, varargs, keywords, defaults = inspect.getargspec(func)
    if arg_name not in args_names:
        raise ValueError("Wrong arg_name value: {}".format(arg_name))

    arg_info = {
        'name': arg_name,
        'value': None,
        'type': None,
        'index': None
    }
    try:
        args_names.remove('self')
        offset = 1
    except ValueError:
        offset = 0
    arg_index = args_names.index(arg_name)

    if len(passed_args) - offset > arg_index:
        arg_info["type"] = "args"
        arg_info["value"] = passed_args[arg_index]
        arg_info['index'] = arg_index
    elif arg_name in passed_kwargs:
        arg_info["type"] = "kwargs"
        arg_info["value"] = passed_kwargs[arg_name]
    else:
        arg_info["type"] = "default"
        default_values = dict(zip(args_names[-len(defaults):], defaults))
        arg_info["value"] = default_values[arg_name]
    return arg_info


def set_arg_value(arg_info, args, kwargs):
    if arg_info["type"] == "kwargs":
        kwargs[arg_info["name"]] = arg_info["value"]
    elif arg_info["type"] == "args":
        args = list(args)
        args[arg_info["index"]] = arg_info["value"]
        args = tuple(args)
    return args, kwargs
